urlset:
{%- set posts_url = get_url(path="@/posts/_index.md") %}
{%- set posts_section = get_section(path="posts/_index.md") %}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink == posts_url and posts_section.pages | length == 0 %}{% continue %}{% endif %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endfor %}
